package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import com.ruoyi.medical.persistence.mapper.*;import java.util.*;import java.time.*;import java.math.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
public class RuntimeRetentionTest extends RuntimeRetentionFixture {
 public RuntimeRetentionTest()throws Exception{super();}
 @Test void actualApprovalAndBothTermsBecomePrivateProof()throws Exception{within(()->{var proof=authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION");assertEquals(id(4),proof.policyRevision());assertEquals(2,proof.terms().size());proof.requireUnchanged();});}
 @Test void currentApprovalRevocationAndExpiryReject()throws Exception{for(String state:List.of("DISABLED","REVOKED")){grant=grant("RUNTIME_RETENTION_APPROVAL",state,null);within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}grant=grant("RUNTIME_RETENTION_APPROVAL","ACTIVE",now);within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}
 @Test void simulationPurposeCannotStandForRuntimeApproval()throws Exception{grant=grant("SIMULATION_EVALUATION","ACTIVE",null);within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}
 @Test void missingAndAmbiguousPolicyNeverChooseLatest()throws Exception{when(mapper.candidates(anyMap())).thenReturn(List.of());within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));when(mapper.candidates(anyMap())).thenReturn(List.of(id(4),id(9)));within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}
 @Test void missingOriginalOperationFailsClosed()throws Exception{when(mapper.operation(anyMap())).thenReturn(List.of());within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}
 @Test void sourceOnlyAndMismatchedStartEventAreRejected()throws Exception{((ObjectNode)request.at("/terms/0")).put("category","SOURCE");assertThrows(SchemaRejection.class,()->schema.validate("RetentionRequest",request));((ObjectNode)request.at("/terms/0")).put("category","RUN").put("start_event","STREAM_CREATED");assertThrows(SchemaRejection.class,()->schema.validate("RetentionRequest",request));}
 @Test void forgedBodyHashFailsEvenWithUnchangedReceipt()throws Exception{request.put("reason","altered");row=new RuntimeRetentionMapper.Row(row.tenantId(),row.projectId(),row.policyRevision(),row.fixedJson(),schema.canonical(request),row.requestHash(),row.contentHash(),row.operationId(),row.key(),row.creator(),row.createdAt(),row.classification(),row.schemaVersion(),row.manifest(),row.auditId(),row.eventId(),row.receiptJson(),row.sessionId(),row.contextJson());within(()->assertThrows(TenantAccessException.class,()->authority.requireForRun(a,id(3),"INTERNAL","RUN_CREATION")));}
 @Test void fixedWorkerProofMatchesActualOwnerRevisionAndHash()throws Exception{within(()->{var proof=authority.requireFixedForRun(a,id(4),row.contentHash(),id(3),"INTERNAL","RUN_CREATION");assertEquals("PROJECT",proof.ownerScope().resource_kind());assertEquals(id(3),proof.ownerScope().resource_id());assertEquals(id(1),proof.ownerScope().tenant_id());assertThrows(TenantAccessException.class,()->authority.requireFixedForRun(a,id(99),row.contentHash(),id(3),"INTERNAL","RUN_CREATION"));assertThrows(TenantAccessException.class,()->authority.requireFixedForRun(a,id(4),"0".repeat(64),id(3),"INTERNAL","RUN_CREATION"));});}
 @Test void fixedWorkerProofCannotBypassCurrentSelectionOrRetirement()throws Exception{within(()->{when(mapper.candidates(anyMap())).thenReturn(List.of());assertThrows(TenantAccessException.class,()->authority.requireFixedForRun(a,id(4),row.contentHash(),id(3),"INTERNAL","RUN_CREATION"));});}
 public static void main(String[]args)throws Exception{int n=0;for(var method:RuntimeRetentionTest.class.getDeclaredMethods())if(method.isAnnotationPresent(Test.class)){try{method.invoke(new RuntimeRetentionTest());System.out.println("PASS "+method.getName());n++;}catch(java.lang.reflect.InvocationTargetException e){throw new RuntimeException(method.getName(),e.getCause());}}System.out.println("PASS "+n+" retention runtime tests");}
}
